import re
from decimal import Decimal

_MAX_CENTS = 100_000_000  # 1000000.00
_STRING_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)


def _to_cents(value):
    """Validate a monetary amount and return it as an exact integer count of cents.

    Uses no arithmetic under the decimal context, so it is exact at any precision.
    """
    if isinstance(value, bool):
        raise ValueError("amount must not be a bool")
    if isinstance(value, Decimal):
        dec = value
    elif isinstance(value, int):
        dec = Decimal(value)
    elif isinstance(value, str):
        if _STRING_RE.fullmatch(value) is None:
            raise ValueError(f"invalid amount string: {value!r}")
        dec = Decimal(value)  # exact; the constructor ignores the context
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not dec.is_finite():
        raise ValueError("amount must be finite")
    if dec <= 0:
        raise ValueError("amount must be positive")
    if dec > Decimal("1000000.00"):
        raise ValueError("amount exceeds 1000000.00")

    sign, digits, exp = dec.as_tuple()
    coef = "".join(map(str, digits))
    # Exact scaled value is coef * 10**(exp + 2) cents; it must be an integer.
    trailing = len(coef) - len(coef.rstrip("0"))
    if exp + trailing < -2:
        raise ValueError("amount is not representable in cents")
    shift = exp + 2
    if shift >= 0:
        cents = coef + "0" * shift
    else:
        cents = coef[: len(coef) + shift]  # dropped digits are all zero
    return int(cents)


def _from_cents(cents):
    """Build an exact Decimal with exponent -2 from an integer count of cents."""
    digits = tuple(int(c) for c in str(cents))
    return Decimal((0, digits, -2))


def parse_amount(value):
    return _from_cents(_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
